import { createRoot } from 'react-dom/client';
import App from './App.tsx';
import './index.css';

// Register the auto-updating service worker (generated by vite-plugin-pwa)
// This is a no-op in development; the SW is only served in production.
import { registerSW } from 'virtual:pwa-register';
registerSW({ immediate: true });

// Disable iOS Safari pinch-zoom gestures
document.addEventListener(
  'gesturestart',
  (e) => {
    e.preventDefault();
  },
  { passive: false }
);

document.addEventListener(
  'touchmove',
  (e) => {
    if ((e as TouchEvent).touches && (e as TouchEvent).touches.length > 1) {
      e.preventDefault();
    }
  },
  { passive: false }
);

createRoot(document.getElementById('root')!).render(<App />);
